var addrKey = (a) => {
	const first = (a ?? "").toLowerCase().split(",").find((x) => /\d/.test(x) && /[a-z\u00c0-\u024f]{3}/.test(x)) ?? "";
	const street = first.replace(/\d[\s\S]*$/, "").replace(/[\s.\-\/]+/g, "") || first.replace(/[\d\s.\-\/]+/g, "");
	const num = (first.match(/\d+/) ?? [""])[0];
	return street && num ? `${street}#${num}` : "";
};
