var hpLangs = (x) => (x?.langs?.length ? x.langs : ["en", "es"]).filter((l) => HP_LANGS.includes(l));
var hpSlugify = (s) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/&/g, " and ").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
